 1→import { useState } from 'react';
 2→import { useTranslation } from '../hooks/useTranslation';
 3→import { createSkill } from '../services/skillsService';
 4→import './CreateSkillDialog.css';
 5→
 6→interface CreateSkillDialogProps {
 7→  onClose: () => void;
 8→  onCreated: () => void;
 9→}
10→
11→export function CreateSkillDialog({ onClose, onCreated }: CreateSkillDialogProps) {
12→  const { t } = useTranslation();
13→  const [name, setName] = useState('');
14→  const [description, setDescription] = useState('');
15→  const [content, setContent] = useState('');
16→  const [error, setError] = useState('');
17→  const [saving, setSaving] = useState(false);
18→
19→  const handleSubmit = async () => {
20→    setError('');
21→    if (!name.trim() || !description.trim() || !content.trim()) {
22→      setError('All fields are required.');
23→      return;
24→    }
25→    setSaving(true);
26→    try {
27→      await createSkill({ name: name.trim(), description: description.trim(), content: content.trim() });
28→      onCreated();
29→      onClose();
30→    } catch (e) {
31→      setError(e instanceof Error ? e.message : 'Failed to create skill');
32→    } finally {
33→      setSaving(false);
34→    }
35→  };
36→
37→  return (
38→    <div className="create-skill-overlay" onClick={onClose}>
39→      <div className="create-skill-dialog" onClick={(e) => e.stopPropagation()}>
40→        <h3 className="create-skill-dialog__title">{t('createSkill')}</h3>
41→        {error && <p className="create-skill-dialog__error">{error}</p>}
42→        <label className="create-skill-dialog__label">{t('skillNameLabel')}</label>
43→        <input
44→          className="create-skill-dialog__input"
45→          value={name}
46→          onChange={(e) => setName(e.target.value)}
47→          placeholder={t('skillNamePlaceholder')}
48→        />
49→        <label className="create-skill-dialog__label">{t('skillDescriptionLabel')}</label>
50→        <input
51→          className="create-skill-dialog__input"
52→          value={description}
53→          onChange={(e) => setDescription(e.target.value)}
54→          placeholder={t('skillDescriptionPlaceholder')}
55→        />
56→        <label className="create-skill-dialog__label">{t('skillContentLabel')}</label>
57→        <textarea
58→          className="create-skill-dialog__textarea"
59→          value={content}
60→          onChange={(e) => setContent(e.target.value)}
61→          placeholder={t('skillContentPlaceholder')}
62→          rows={8}
63→        />
64→        <div className="create-skill-dialog__actions">
65→          <button className="create-skill-dialog__cancel" onClick={onClose}>{t('cancel')}</button>
66→          <button className="create-skill-dialog__save" onClick={handleSubmit} disabled={saving}>
67→            {saving ? '...' : t('createSkill')}
68→          </button>
69→        </div>
70→      </div>
71→    </div>
72→  );
73→}
