 1→import { useState, useEffect, useRef } from 'react';
 2→import type { SkillInfo } from '../types';
 3→import './SlashCommandMenu.css';
 4→
 5→interface SlashCommandMenuProps {
 6→  skills: SkillInfo[];
 7→  filter: string;
 8→  onSelect: (skillName: string) => void;
 9→  onClose: () => void;
10→}
11→
12→export function SlashCommandMenu({ skills, filter, onSelect, onClose }: SlashCommandMenuProps) {
13→  const [selectedIndex, setSelectedIndex] = useState(0);
14→  const listRef = useRef<HTMLUListElement>(null);
15→
16→  const filtered = skills.filter((s) =>
17→    !s.disabled && s.name.includes(filter.toLowerCase())
18→  );
19→
20→  useEffect(() => {
21→    setSelectedIndex(0);
22→  }, [filter]);
23→
24→  useEffect(() => {
25→    const handleKeyDown = (e: KeyboardEvent) => {
26→      if (e.key === 'ArrowDown') {
27→        e.preventDefault();
28→        setSelectedIndex((i) => Math.min(i + 1, filtered.length - 1));
29→      } else if (e.key === 'ArrowUp') {
30→        e.preventDefault();
31→        setSelectedIndex((i) => Math.max(i - 1, 0));
32→      } else if (e.key === 'Enter' && filtered.length > 0) {
33→        e.preventDefault();
34→        onSelect(filtered[selectedIndex].name);
35→      } else if (e.key === 'Escape') {
36→        e.preventDefault();
37→        onClose();
38→      }
39→    };
40→    document.addEventListener('keydown', handleKeyDown);
41→    return () => document.removeEventListener('keydown', handleKeyDown);
42→  }, [filtered, selectedIndex, onSelect, onClose]);
43→
44→  useEffect(() => {
45→    const el = listRef.current?.children[selectedIndex] as HTMLElement | undefined;
46→    el?.scrollIntoView({ block: 'nearest' });
47→  }, [selectedIndex]);
48→
49→  if (filtered.length === 0) return null;
50→
51→  return (
52→    <div className="slash-menu">
53→      <ul className="slash-menu__list" ref={listRef}>
54→        {filtered.map((skill, i) => (
55→          <li
56→            key={skill.name}
57→            className={`slash-menu__item ${i === selectedIndex ? 'slash-menu__item--selected' : ''}`}
58→            onMouseEnter={() => setSelectedIndex(i)}
59→            onClick={() => onSelect(skill.name)}
60→          >
61→            <span className="slash-menu__name">/{skill.name}</span>
62→            <span className="slash-menu__desc">{skill.description}</span>
63→          </li>
64→        ))}
65→      </ul>
66→    </div>
67→  );
68→}
