 31→function AppContent({
 32→  tables,
 33→  refreshTables,
 34→  sessionId,
 35→}: {
 36→  tables: TableInfo[];
 37→  refreshTables: () => Promise<void>;
 38→  sessionId: string;
 39→}) {
 40→  const { theme, toggleTheme } = useTheme();
 41→  const { language, setLanguage, t } = useTranslation();
 42→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 43→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 44→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 45→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 46→  );
 47→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 48→  const [agentOpen, setAgentOpen] = useState(true);
 49→  const [pendingSkillCommand, setPendingSkillCommand] = useState<string | null>(null);
 50→
 51→  useEffect(() => {
 52→    document.title = t('appTitle');
 53→  }, [t]);
 54→
 55→  useEffect(() => {
 56→    if (tables.length === 0) {
 57→      setQueryResult(null);
 58→      setError(null);
 59→      setEditorQuery(undefined);
 60→    }
 61→  }, [tables]);
 62→
 63→  const errorMessage = error
 64→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 65→    : null;
 66→
 67→  const handleAgentToggle = () => {
 68→    setAgentOpen((prev) => !prev);
 69→  };
 70→
 71→  const handleLoadSample = useCallback(async () => {
 72→    setError(null);
 73→    try {
 74→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
 75→      if (!response.ok) throw new Error('Failed to load sample dataset');
 76→      await refreshTables();
 77→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 78→    } catch (e) {
 79→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 80→    }
 81→  }, [refreshTables, sessionId]);
 82→
 83→  const handleFileUpload = useCallback(
 84→    async (files: File[]) => {
 85→      setError(null);
 86→
 87→      // Check for duplicate filenames within the batch
 88→      const batchDuplicates = findDuplicateFileNames(files);
 89→      if (batchDuplicates.length > 0) {
 90→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
 91→        return;
 92→      }
 93→
 94→      // Check for filenames that match already-uploaded table names
 95→      const existingNames = new Set(tables.map((tbl) => tbl.name));
 96→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
 97→      if (alreadyUploaded.length > 0) {
 98→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
 99→        return;
100→      }
101→
102→      let lastName = '';
103→      try {
104→        for (const file of files) {
105→          const formData = new FormData();
106→          formData.append('file', file);
107→          const response = await fetch('/api/upload', {
108→            method: 'POST',
109→            headers: { 'X-Session-ID': sessionId },
110→            body: formData,
111→          });
112→          if (!response.ok) {
113→            const errorData = await response.json();
114→            throw new Error(errorData.detail || 'Failed to upload file');
115→          }
116→          const result = await response.json();
117→          // Handle both single table and array of tables (Excel with multiple sheets)
118→          if (Array.isArray(result)) {
119→            lastName = result[result.length - 1]?.name || '';
120→          } else {
121→            lastName = result.name;
122→          }
123→        }
124→        await refreshTables();
125→        if (lastName) {
126→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
127→        }
128→      } catch (e) {
129→        setError(e instanceof Error ? e.message : 'Failed to upload file');
130→      }
131→    },
132→    [refreshTables, sessionId, tables]
133→  );
134→
135→  const handleQueryExecute = useCallback(
136→    async (sql: string) => {
137→      setError(null);
138→      setQueryResult(null);
139→      try {
140→        const start = performance.now();
141→        const response = await fetch('/api/query', {
142→          method: 'POST',
143→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
144→          body: JSON.stringify({ sql }),
145→        });
146→        const elapsed = performance.now() - start;
147→
148→        if (!response.ok) {
149→          const errorData = await response.json();
150→          throw new Error(errorData.detail || 'Query execution failed');
151→        }
152→
153→        const result = await response.json();
154→        setQueryResult({
155→          columns: result.columns,
156→          rows: result.rows,
157→          rowCount: result.rowCount,
158→          executionTimeMs: elapsed,
159→          resultType: result.resultType,
160→        });
161→        await refreshTables();
162→      } catch (e) {
163→        setError(e instanceof Error ? e.message : 'Query execution failed');
164→      }
165→    },
166→    [refreshTables, sessionId]
167→  );
168→
169→  const handleTableClick = useCallback((tableName: string) => {
170→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
171→  }, []);
172→
173→  const handleTableDelete = useCallback(async (tableName: string) => {
174→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
175→    try {
176→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
177→        method: 'DELETE',
178→        headers: { 'X-Session-ID': sessionId },
179→      });
180→      if (!response.ok) throw new Error('Failed to delete table');
181→      await refreshTables();
182→    } catch (e) {
183→      setError(e instanceof Error ? e.message : 'Failed to delete table');
184→    }
185→  }, [refreshTables, t, sessionId]);
186→
187→  const handleDeleteAll = useCallback(async () => {
188→    if (tables.length === 0) return;
189→    if (!confirm(t('deleteAllTablesConfirm'))) return;
190→    try {
191→      for (const table of tables) {
192→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
193→          method: 'DELETE',
194→          headers: { 'X-Session-ID': sessionId },
195→        });
196→        if (!response.ok) throw new Error('Failed to delete table');
197→      }
198→      await refreshTables();
199→    } catch (e) {
200→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
201→    }
202→  }, [tables, refreshTables, t, sessionId]);
203→
204→  const appClass = [
205→    'app',
206→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
207→  ].filter(Boolean).join(' ');
208→
209→  const themeIcon = theme === 'dark' ? (
